args.content:
$files = Get-ChildItem -Path "dosyalar" -File -Recurse | Select-Object @{Name="RelativePath"; Expression={$_.FullName.Replace((Get-Location).ToString() + "\", "").Replace("\", "/")}}, FullName, Length

$groups = $files | Group-Object {
    if ($_.Length -eq 0) {
        "empty"
    } else {
        $hash = Get-FileHash -Path $_.FullName -Algorithm MD5
        $hash.Hash
    }
} | Where-Object { $_.Count -gt 1 }

$results = @()

foreach ($group in $groups) {
    $paths = $group.Group | Sort-Object RelativePath | ForEach-Object { $_.RelativePath }
    $results += [string]::Join(" | ", $paths)
}

$sortedResults = $results | Sort-Object
$sortedResults | Out-File -FilePath "kopyalar.txt" -Encoding utf8

